namespace {
struct DiplomaticSnapshot {DiplomacyState diplomacy;EnvoyTaskState envoy;};
DiplomaticSnapshot snapshot(ResidentReplaySession& session){const auto state=export_state(session);return {need(decode_diplomacy_state(field(state,"diplomacy")),"Decode actual diplomacy"),need(decode_envoy_task_state(field(state,"envoy_tasks")),"Decode actual envoy responsibility")};}
V diplomatic_page(ResidentReplaySession& session){return query(session,"diplomacy",site_args(session));}
V diplomatic_action(ResidentReplaySession& session,const StableId& kind){const auto page=diplomatic_page(session);auto action=find_action(page,kind);if(!action.find("command"))trace.push_back(boundary::obj({{"missing_action",V{kind}},{"diplomacy_page",page},{"interaction",query(session,"interaction_view")}}));check(action.find("command"),"Actual diplomacy action missing: "+kind);return action;}
void readonly_quote(ResidentReplaySession& session,const V& action){const auto before=need(session.checkpoint(),"Before diplomacy quote");call(session,LiveOperationKind::preview,boundary::obj({{"kind",field(action,"command")},{"params",field(action,"params")},{"actor_id",field(query(session,"command_context"),"actor_id")}}),"Actual diplomacy quote");check(before==need(session.checkpoint(),"After diplomacy quote"),"Diplomacy quote changed actual world");}
void save_bank(ResidentReplaySession& session,const std::filesystem::path& root,const StableId& name){const auto bytes=need(session.checkpoint(),"Checkpoint "+name);std::ofstream out(root/(name+".bank"),std::ios::binary);out.write(reinterpret_cast<const char*>(bytes.data()),static_cast<std::streamsize>(bytes.size()));check(bool(out),"Save original bank "+name);std::ofstream diagnostic(root/(name+".json"));diagnostic<<need(render_boundary_json(export_state(session)),"Render original bank diagnostic")<<'\n';check(bool(diagnostic),"Save diagnostic "+name);}
StableId accept_self_mission(ResidentReplaySession& session){check(text(query(session,"command_context"),"actor_id")=="society::actor.city_steward","Actual authored city steward required");auto initial=snapshot(session);check(initial.diplomacy.offers.empty()&&initial.envoy.envoy_contracts.empty(),"Fresh author scene has fabricated diplomacy");
    auto proposal=diplomatic_action(session,"diplomatic_propose_passage");readonly_quote(session,proposal);submit_action(session,proposal);auto issued=snapshot(session);check(issued.diplomacy.offers.size()==1&&issued.diplomacy.missions.empty()&&issued.envoy.envoy_contracts.empty(),"Proposal forged a mission or Task");
    auto commission=diplomatic_action(session,"diplomatic_commission_envoy");readonly_quote(session,commission);submit_action(session,commission);auto commissioned=snapshot(session);check(commissioned.diplomacy.missions.size()==1&&commissioned.envoy.envoy_contracts.empty(),"Commission silently accepted responsibility");
    auto acceptance=diplomatic_action(session,"envoy_accept");readonly_quote(session,acceptance);auto request=envelope(session,"envoy_accept",field(acceptance,"params"));auto first=call(session,LiveOperationKind::command,request,"Accept actual self-envoy responsibility");auto bytes=need(session.checkpoint(),"Accepted state before replay");auto repeated=call(session,LiveOperationKind::command,request,"Replay same envoy acceptance");check(compare_boundary(first,repeated).exact()&&bytes==need(session.checkpoint(),"Accepted state after replay"),"Acceptance replay duplicated responsibility");
    auto accepted=snapshot(session);check(accepted.envoy.envoy_contracts.size()==1&&accepted.diplomacy.presentations.empty(),"Acceptance forged delivery");const auto& contract=accepted.envoy.envoy_contracts.rows().front().second;check(!contract.action&&!contract.delivery&&!contract.completion&&!contract.acceptance.return_report_required,"Author self-envoy acceptance started work or requires self report");return contract.acceptance.task_id;
}
// 每段真实导航与原活动推进都从公共接口执行，既不改位置也不挪时钟到截止前。
void travel_to_recipient(ResidentReplaySession& session){for(Integer step=0;step<16;++step){const auto location=query(session,"journey_location");if(location.find("place_id")&&text(location,"place_id")=="society::place.sword_gate")return;const auto current_action=field(query(session,"character_summary"),"action");if(current_action.find("kind")&&text(current_action,"kind")=="travel"){advance(session);continue;}const auto page=diplomatic_page(session);auto next=find_action(page,"move_local");if(!next.find("command"))next=find_action(page,"travel");if(next.find("command")){readonly_quote(session,next);submit_action(session,next);continue;}const auto action=field(query(session,"character_summary"),"action");if(action.find("kind")&&text(action,"kind")=="travel"){advance(session);continue;}trace.push_back(boundary::obj({{"missing_navigation",page},{"location",location},{"action",action}}));check(false,"No current lawful navigation or real travel activity");}check(false,"Actual authored route exceeded bounded navigation steps");}
// 选原场景公开的实际同场代表岗位；政治层再次核Office/Grant，不能凭一个名字直接呈递。
void meet_recipient(ResidentReplaySession& session){auto sidebar=query(session,"place_sidebar");V selected;for(const auto& person:boundary::array(field(sidebar,"people"),"people")){if(text(person,"actor_id")!="society::actor.sect_steward")continue;for(const auto& topic:boundary::array(field(person,"topics"),"topics")){if(!boundary::get_bool(topic,"available","topic"))continue;auto params=boundary::obj({{"role_id",field(topic,"role_id")}});auto quote=call(session,LiveOperationKind::preview,boundary::obj({{"kind",V{"talk"}},{"params",params},{"actor_id",field(query(session,"command_context"),"actor_id")}}),"Preview current representative meeting",false);if(boundary::get_bool(quote,"ok","meeting quote")){selected=params;break;}}}if(!selected.find("role_id"))trace.push_back(boundary::obj({{"representative_sidebar",sidebar}}));check(selected.find("role_id"),"No real present representative meeting candidate");submit(session,"talk",selected);auto interaction=query(session,"interaction_view");check(text(interaction,"phase")=="say"||text(interaction,"phase")=="choice","Real meeting did not reach contact phase");}
// 从自然active银行派生合法ID耗尽边界；先完整安装，再证明原候选晚拒后整世界未发布。
void late_cancellation_atomicity(ResidentReplaySession& active,const V& catalog,const StableId& task_id){
    const auto original=need(active.checkpoint(),"Original active bank before isolated exhaustion fixture");auto state=export_state(active);check(state.find("next_instance_id"),"Actual export lacks instance counter");state.find("next_instance_id")->data=std::numeric_limits<Integer>::max();
    // 正式native导出沿原选择头准备目录；不借legacy GD seed initialize重选人物表。
    auto selector=create_resident_replay_session();const auto selection=need(selector->inspect_checkpoint_selection(original),"Actual native bank selection header");const auto& selected=field(selection,"catalog");CatalogIdentity expected;expected.content_id=text(selected,"content_id");expected.content_version=text(selected,"content_version");expected.content_digest=text(selected,"content_digest");expected.ruleset_id=text(selected,"ruleset_id");expected.schema_sha256=text(selected,"schema_sha256");expected.artifact_sha256=text(selected,"artifact_sha256");if(selected.find("pack_set_digest"))expected.pack_set_digest=text(selected,"pack_set_digest");for(const auto& module:boundary::array(field(selected,"module_versions"),"modules"))expected.module_versions.emplace_back(text(module,"name"),text(module,"version"));auto prepared=need(prepare_native_catalog(catalog,text(selection,"scenario_id"),expected),"Prepare exact original native catalog");
    ResidentWorld isolated;auto isolated_seed=need(decode_world_seed(state,*prepared),"Decode legal exhausted counter source");need(isolated.install(prepared,std::move(isolated_seed)),"Install and fully validate legal exhausted-counter derivative");auto cancel=diplomatic_action(active,"envoy_cancel");const auto command_context=query(active,"command_context");const auto identity=need(isolated.identity(),"Isolated real World identity");CommandEnvelope request;request.world_id=identity.world_id;request.execution_epoch=identity.execution_epoch;request.expected_revision=identity.revision;request.actor_id=text(command_context,"actor_id");request.request_seq=boundary::get_int(command_context,"next_request_seq","context");request.payload=std::make_shared<const CommandPayload>(need(decode_resident_command("envoy_cancel",field(cancel,"params")),"Decode actual cancellation params"));const auto before=need(isolated.checkpoint(),"Before late cancellation refusal");need(isolated.preview(request),"Actual isolated cancellation preview");check(before==need(isolated.checkpoint(),"After isolated preview"),"Isolated preview changed world");auto refused=isolated.submit(request);check(!refused.ok&&refused.error.original.code=="InstanceIdOverflow","Exhausted cancellation did not reach expected real late failure: "+refused.error.original.code);check(before==need(isolated.checkpoint(),"After late cancellation refusal"),"Late cancellation published a partial multi-domain release");
    // 同一已通过安装的源再造一个不发布的实际WorldBundle候选，直接观察原release先发生。
    auto seed=need(decode_world_seed(state,*prepared),"Decode same exhausted counter state");WorldBundle candidate(prepared,std::move(seed));need(candidate.validate(),"Validate direct real candidate before fault");const auto actor=candidate.common.state().metadata.player_actor_id;const auto* link=candidate.envoy_tasks.envoy_contracts.find(task_id);check(link&&link->action,"Direct candidate lacks actual handover");const auto action_id=link->action->action_id;const auto provider=link->action->context.provider_actor_id;auto ia=candidate.services.interaction_access();auto context=candidate.diplomacy_write(ia);DiplomacyCommand command=DiplomaticEnvoyCancelCommand{task_id,candidate.common.revision()};auto quote=need(preview_diplomacy_business(context.read(),actor,command),"Direct actual cancellation quote");auto late=apply_diplomacy_business(context,actor,command,quote);check(!late.ok&&late.error.original.code=="InstanceIdOverflow","Direct candidate did not hit the same failure");check(!candidate.common.action(action_id)&&candidate.common.actor(actor)->action_id.empty()&&candidate.common.actor(provider)->action_id.empty(),"Failure was not after actual Action and both participants released");check(original==need(active.checkpoint(),"Original natural active bank after isolated probes"),"Isolated boundary fixture mutated natural active world");trace.push_back(boundary::obj({{"late_cancellation_fixture",V{"natural active export with only next_instance_id=INT64_MAX; validated before command"}},{"code",V{"InstanceIdOverflow"}},{"whole_checkpoint_unchanged",V{true}},{"actual_release_observed_before_failure",V{true}}}));
}
void completed_mission(ResidentReplaySession& session,const V& catalog,const std::filesystem::path& root){
    // 作者已有城吏俸给在第4半日从工资专户支付12，先真实取得私人旅费再出使。
    auto initial=export_state(session);check(boundary::get_int(field(field(initial,"wallets"),"society::wallet.city_steward"),"balance","private wallet")==0,"Actual initial private wallet changed");for(Integer tick=0;tick<4;++tick)advance(session);auto paid=export_state(session);check(boundary::get_int(field(field(paid,"wallets"),"society::wallet.city_steward"),"balance","private wallet")==12,"Original city salary did not actually fund private wallet at due tick4");check(boundary::get_int(field(field(paid,"wallets"),"society::wallet.city_wages"),"balance","wage source")==228,"Original salary did not debit real wage source");trace.push_back(boundary::obj({{"travel_money_source",V{"obligation.city_salary due4 actual payment"}},{"private_balance",V{Integer{12}}},{"wage_source_balance",V{Integer{228}}}}));const auto task_id=accept_self_mission(session);save_bank(session,root,"accepted");travel_to_recipient(session);meet_recipient(session);auto deliver=diplomatic_action(session,"envoy_deliver");readonly_quote(session,deliver);submit_action(session,deliver);auto active=snapshot(session);const auto* started=active.envoy.envoy_contracts.find(task_id);check(started&&started->action&&!started->delivery&&!started->completion&&active.diplomacy.presentations.empty(),"Starting real handover forged completed delivery");save_bank(session,root,"active");late_cancellation_atomicity(session,catalog,task_id);auto continuation=diplomatic_action(session,"advance");readonly_quote(session,continuation);const auto before=need(session.identity(),"Handover before actual half-day").tick;submit_action(session,continuation);check(need(session.identity(),"Handover after actual half-day").tick==before+1,"Original half-day command did not commit exactly once");auto complete=snapshot(session);const auto* task=complete.envoy.envoy_contracts.find(task_id);check(task&&task->delivery&&task->completion&&task->completion->result==EnvoyTaskResult::completed&&!task->action,"Actual handover did not finish the same self-envoy Task");check(complete.diplomacy.presentations.size()==1&&complete.diplomacy.replies.empty(),"Handover forged consent or duplicate presentation");const auto& presentation=complete.diplomacy.presentations.rows().front().second;check(presentation.task_binding&&presentation.task_binding->task_id==task_id&&presentation.id==task->delivery->diplomatic_presentation_fact_id,"Task final lacks exact unique political presentation");check(complete.diplomacy.offers.rows().front().second.status==DiplomaticOfferStatus::presented,"Delivered proposal silently activated a treaty");query(session,"journal_text");query(session,"interaction_tasks");trace.push_back(boundary::obj({{"completed_diplomacy_page",diplomatic_page(session)},{"completed_interaction",query(session,"interaction_view")}}));save_bank(session,root,"completed");}
// 明确取消另一正常新局的本人责任，保原签发事实，不能伪造已递交或撤销另一条约。
void cancelled_mission(ResidentReplaySession& session,const std::filesystem::path& root){const auto id=accept_self_mission(session);auto cancel=diplomatic_action(session,"envoy_cancel");readonly_quote(session,cancel);submit_action(session,cancel);auto state=snapshot(session);const auto* task=state.envoy.envoy_contracts.find(id);check(task&&task->completion&&task->completion->result==EnvoyTaskResult::cancelled&&!task->delivery,"Actual cancellation did not preserve undelivered responsibility");check(state.diplomacy.presentations.empty()&&state.diplomacy.replies.empty()&&state.diplomacy.offers.size()==1,"Cancellation changed political delivery history");save_bank(session,root,"cancelled");}
}
#ifndef DIPLOMACY_BOUNDARY_HELPERS_ONLY
int main(int argc,char** argv){try{check(argc==5,"Usage: diplomacy_boundary_test CATALOG_JSON NATIVE_REQUEST_JSON RESULT_JSON BANK_DIRECTORY");const auto catalog=read(argv[1]),request=read(argv[2]);check(text(request,"scenario_id")=="civicecon::scenario.qingchuan_diplomacy","Actual diplomacy author scenario required");std::filesystem::create_directories(argv[4]);auto session=create_resident_replay_session();need(session->initialize_native(catalog,request),"Install actual composed diplomacy scene");completed_mission(*session,catalog,argv[4]);auto cancelled=create_resident_replay_session();need(cancelled->initialize_native(catalog,request),"Install same author scene for actual cancellation");cancelled_mission(*cancelled,argv[4]);save(argv[3],true);std::cout<<"DIPLOMACY_BOUNDARY "<<checks<<" checks 0 failures; real proposal/commission/accept/navigation/meeting/handover/final/cancel; no treaty activation\n";return 0;}catch(const std::exception& error){if(argc==5)try{save(argv[3],false,error.what());}catch(...){}std::cerr<<"DIPLOMACY_BOUNDARY FAIL "<<error.what()<<" after "<<checks<<" checks\n";return 1;}}

#endif
